import test from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { readFile } from 'node:fs/promises';

// Evaluate the actual worker source generated by the existing Preview builder.
const builder = await readFile(new URL('./build-integrated-preview.mjs', import.meta.url), 'utf8');
const vercelConfig = JSON.parse(await readFile(new URL('../vercel.json', import.meta.url), 'utf8'));
const source = builder.slice(builder.indexOf('const allow ='), builder.indexOf('await writeFile(resolve(output, "preview-readonly-sw.js")'));
const worker = vm.runInNewContext(`${source}\nworker;`);
async function request(path, { method = 'POST', body, origin = 'https://linswmnnkjxvweumprav.supabase.co', workerSource = worker } = {}) {
  let handler, response, forwarded = 0;
  vm.runInNewContext(workerSource, {
    self: { addEventListener: (name, fn) => { if (name === 'fetch') handler = fn; } },
    URL, Response,
    fetch: async () => { forwarded++; return new Response('{}', { status: 200 }); },
  });
  handler({ request: new Request(origin + path, { method, ...(body === undefined ? {} : { body: JSON.stringify(body) }) }), respondWith: (value) => { response = value; } });
  const result = response ? await response : null;
  return { status: result?.status || 200, forwarded, blocked: result?.headers.get('X-Preview-Write-Blocked') };
}
test('existing accounts can sign in, refresh, read identity and sign out locally', async () => {
  for (const [path, options] of [
    ['/auth/v1/token?grant_type=password', { body: { email: 'test@example.invalid', password: 'synthetic' } }],
    ['/auth/v1/token?grant_type=refresh_token', { body: { refresh_token: 'synthetic' } }],
    ['/auth/v1/user', { method: 'GET' }],
    ['/auth/v1/logout?scope=local', {}],
    ['/auth/v1/otp', { body: { email: 'test@example.invalid', create_user: false } }],
    ['/auth/v1/verify', { body: { email: 'test@example.invalid', type: 'email', token: '123456' } }],
  ]) assert.deepEqual(await request(path, options), { status: 200, forwarded: 1, blocked: null }, path);
});
test('signup, global logout, account mutation, other grants and origins stay blocked', async () => {
  for (const [path, options] of [
    ['/auth/v1/signup', {}], ['/auth/v1/recover', {}], ['/auth/v1/user', { method: 'PUT' }],
    ['/auth/v1/logout', {}], ['/auth/v1/logout?scope=global', {}],
    ['/auth/v1/token?grant_type=pkce', {}], ['/auth/v1/token?grant_type=password', { method: 'GET' }],
    ['/auth/v1/token?grant_type=password', { origin: 'https://other.supabase.co' }],
    ['/auth/v1/token?grant_type=password', { origin: 'http://linswmnnkjxvweumprav.supabase.co' }],
    ['/auth/v1/otp', { body: { email: 'test@example.invalid', create_user: true } }],
    ['/auth/v1/otp', { body: { email: 'test@example.invalid' } }],
    ['/auth/v1/verify', { body: { email: 'test@example.invalid', type: 'signup', token: '123456' } }],
    ['/auth/v1/verify', { body: { phone: 'synthetic', type: 'sms', token: '123456' } }],
  ]) assert.deepEqual(await request(path, options), { status: 403, forwarded: 0, blocked: 'true' }, path);
});
test('profile/product/storage/model writes remain blocked; governed readers still work', async () => {
  for (const [path, options] of [
    ['/rest/v1/users?id=eq.A', { method: 'PATCH', body: { display_name: 'changed' } }],
    ['/rest/v1/rpc/research_state_apply_v1', {}], ['/rest/v1/rpc/claim_daily_credit', {}],
    ['/rest/v1/rpc/admin_research_review', {}], ['/rest/v1/rpc/admin_research_set_publication_v1', {}],
    ['/storage/v1/object/public/example', {}], ['/functions/v1/ask-raziel', {}],
    ['/functions/v1/els-search-bridge', { body: { op: 'save' } }],
  ]) assert.equal((await request(path, options)).status, 403, path);
  assert.equal((await request('/rest/v1/rpc/fn_method_value')).status, 200);
  assert.equal((await request('/rest/v1/rpc/rd_is_admin')).status, 200);
  assert.equal((await request('/rest/v1/rpc/fn_name_protocol', { body: { p_name: 'fixture-name' } })).status, 200);
  assert.equal((await request('/rest/v1/rpc/fn_cross_research', { body: { p_items: ['fixture-name', 'fixture-date'] } })).status, 200);
  assert.equal((await request('/rest/v1/rpc/fn_get_or_create_my_person')).status, 200);
  assert.equal((await request('/rest/v1/rpc/fn_list_family', { body: { p_owner: 'fixture-person' } })).status, 200);
  for (const rpc of ['fn_upsert_self_profile', 'fn_upsert_family_member', 'fn_upsert_family_relation']) {
    assert.deepEqual(await request(`/rest/v1/rpc/${rpc}`, { body: {} }), { status: 403, forwarded: 0, blocked: 'true' }, rpc);
  }
  assert.equal((await request('/functions/v1/els-search-bridge', { body: { op: 'page' } })).forwarded, 1);
});

test('unified working preview blocks Person creation and trace-producing ELS bridge', async () => {
  for (const branch of ['gpt/2029-central-unified-workspace-20261029', 'gpt/2029-central-shell-alignment-20261029', 'gpt/2029-central-topbar-menu-completion-20261029', 'gpt/2029-central-ui-carry-restoration-20261029']) {
    const workerSource = vm.runInNewContext(`${source}\nworker;`, {
      process: { env: { VERCEL_GIT_COMMIT_REF: branch } },
    });
    for (const [path, body] of [
      ['/rest/v1/rpc/fn_get_or_create_my_person', {}],
      ['/functions/v1/els-search-bridge', { op: 'page' }],
      ['/rest/v1/rpc/add_contribution', { p_origin: 'community_2029', p_body: 'synthetic' }],
      ['/rest/v1/rpc/edit_contribution', { p_id: 'synthetic', p_body: 'synthetic' }],
      ['/rest/v1/rpc/remove_contribution', { p_id: 'synthetic' }],
    ]) assert.deepEqual(await request(path, { body, workerSource }), { status: 403, forwarded: 0, blocked: 'true' }, path);
    assert.equal((await request('/rest/v1/rpc/fn_number_lookup', { workerSource })).status, 200);
  }
});

test('Books publication review is preview-only and has no write RPC in the guard', () => {
  assert.match(builder, /VITE_BOOK_PUBLICATION_REVIEW_PREVIEW/);
  assert.doesNotMatch(builder, /admin_research_review|admin_research_set_publication_v1/);
});

test('Community Preview reads use the existing closed public projection for GET and POST', async () => {
  const fields = 'id,parent_id,author_name,author_user_id,author_contributor_id,title,body,reactions,origin,created_at,edited_at,is_deleted,total_count';
  for (const method of ['GET', 'POST']) {
    for (const rpc of ['community_feed_page', 'community_message_context']) {
      const path = `/rest/v1/rpc/${rpc}`;
      assert.equal((await request(`${path}?select=${encodeURIComponent(fields)}`, { method })).status, 200);
      for (const query of ['', '?select=*', '?select=contributor_user_id', `?select=${encodeURIComponent(fields)}&select=*`, '?select=id,private:contributor_avatar_url']) {
        assert.deepEqual(await request(path + query, { method }), { status: 403, forwarded: 0, blocked: 'true' }, `${method} ${rpc} ${query}`);
      }
    }
    for (const rpc of ['community_replies_page', 'community_reply_counts']) {
      assert.deepEqual(await request(`/rest/v1/rpc/${rpc}`, { method }), { status: 403, forwarded: 0, blocked: 'true' });
    }
    for (const path of ['/rest/v1/rpc/%63ommunity_feed_page', '/rest/v1/rpc/%63ommunity_message_context', '/rest/v1/rpc/%63ommunity_replies_page', '/rest/v1/rpc/%63ommunity_reply_counts', '/rest/v1/rpc/community_feed_page%2fextra', '/rest/v1/rpc/COMMUNITY_FEED_PAGE', '/rest/v1/RPC/community_feed_page', '/rest/v1/rpc/community_feed_page/', '/rest/v1/rpc/community_%ZZ']) {
      assert.deepEqual(await request(path + '?select=*', { method }), { status: 403, forwarded: 0, blocked: 'true' }, `${method} ${path}`);
    }
  }
  assert.equal((await request('/storage/v1/object/public/example/%D7%90.jpg', { method: 'GET' })).status, 200, 'encoded source-media names remain readable');
});

test('Life Journey Preview overrides the public catch-all with private no-store headers', () => {
  const catchAllIndex = vercelConfig.headers.findIndex(({ source }) => source === '/(.*)');
  const journeyIndex = vercelConfig.headers.findLastIndex(({ source }) => source === '/2029/journey');
  assert.ok(catchAllIndex >= 0);
  assert.ok(journeyIndex > catchAllIndex);
  const headers = Object.fromEntries(
    vercelConfig.headers[journeyIndex].headers.map(({ key, value }) => [key.toLowerCase(), value]),
  );
  assert.equal(headers['cache-control'], 'private, no-store, max-age=0, must-revalidate');
  assert.equal(headers['x-robots-tag'], 'noindex, nofollow, noarchive');
});
